(7729077, 1272706, 66597, '<td valign="top">Nice choice on post processing. Excellent grungy look.</td>', 'Nice choice on post processing. Excellent grungy look.', '2022-09-02 07:36:46.000000', NULL, 1),
(7729078, 1272695, 66597, '<td valign="top">I love this except for the corner of the car.</td>', 'I love this except for the corner of the car.', '2022-09-02 07:37:59.000000', NULL, 1),
