(7729200, 1272630, 637, '<td valign="top">slice of life! I like the textures of the sand, grass and sky as well as the colors.</td>', 'slice of life! I like the textures of the sand, grass and sky as well as the colors.', '2022-09-05 18:03:17.000000', NULL, 1),
(7729201, 1272651, 637, '<td valign="top">Strong image, love the colors and the texture of the sky... especially like the lights in the town in the foreground.</td>', 'Strong image, love the colors and the texture of the sky... especially like the lights in the town in the foreground.', '2022-09-05 18:03:53.000000', NULL, 1),
(7729203, 1272695, 637, '<td valign="top">For me this picture is all about the use of monochrome and the texture of the sky.  Well-composed, and nice geometry... Even the extraneous vehicles and garbage cans serve the image.</td>', 'For me this picture is all about the use of monochrome and the texture of the sky.  Well-composed, and nice geometry... Even the extraneous vehicles and garbage cans serve the image.', '2022-09-05 18:07:34.000000', NULL, 1),
(7729204, 1272561, 637, '<td valign="top">Yes, Industrial, but not all that interesting to me.... nice dof and composition.</td>', 'Yes, Industrial, but not all that interesting to me.... nice dof and composition.', '2022-09-05 18:08:04.000000', NULL, 1),
(7729205, 1272666, 637, '<td valign="top">Although the cement plant lights interplay well with the twilight sky, I''d try a different composition.  I''m wondering how the image would look if you had cropped out the sky and increased the "real estate" of the blue water instead.  Love the colors.</td>', 'Although the cement plant lights interplay well with the twilight sky, I''d try a different composition.  I''m wondering how the image would look if you had cropped out the sky and increased the "real estate" of the blue water instead.  Love the colors.', '2022-09-05 18:13:01.000000', NULL, 1),
(7729206, 1272694, 637, '<td valign="top">Well-lit and well-composed. I would like to see more that that colorful and textured sky.</td>', 'Well-lit and well-composed. I would like to see more that that colorful and textured sky.', '2022-09-05 18:14:06.000000', NULL, 1),
(7729207, 1272645, 637, '<td valign="top">Nice colors... also like the contrast of the plant with the apartment house/hotel on the right side.</td>', 'Nice colors... also like the contrast of the plant with the apartment house/hotel on the right side.', '2022-09-05 18:16:53.000000', NULL, 1),
